          "claim": "Inside-payment logs about 2000 SEVERE dispatcher exceptions in the abnormal window, with none in the normal period."
        },
        {
          "kind": "log",
          "sql": "SELECT time, level, message FROM abnormal_logs WHERE service_name='ts-inside-payment-service' AND level='SEVERE' LIMIT 2",
          "claim": "The SEVERE logs read 'Request processing failed; nested exception is java.lang.IllegalArgumentException: URI is not absolute'."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_status_code, attr_http_response_status_code, count(*) c, round(avg(duration)/1e6,1) avg_ms FROM abnormal_traces WHERE service_name='ts-inside-payment-service' AND span_name LIKE '%inside_payment%' GROUP BY ALL",
          "claim": "Inside-payment's inside_payment POST spans are all Error with HTTP 500 and about 11 ms average."
        },
        {
          "kind": "trace",
          "sql": "SELECT date_trunc('minute', time) m, service_name, count(*) n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE service_name='ts-inside-payment-service' AND span_name LIKE '%inside_payment%' GROUP BY ALL ORDER BY 1",
          "claim": "Nearly every inside-payment request errors in every abnormal minute, from the start of the window."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-inside-payment-service",
